        PropertyMetadata(name='date_published', schema_name='datePublished', schema_url='https://schema.org/datePublished', ranges=('Date', 'DateTime'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('Certification', 'CreativeWork'), external_domains=(), comment='Date of first publication or broadcast. For example the date a [[CreativeWork]] was broadcast or a [[Certification]] was issued.', label='datePublished', contributors=(), sources=()),
