        PropertyMetadata(name='digital_source_type', schema_name='digitalSourceType', schema_url='https://schema.org/digitalSourceType', ranges=('IPTCDigitalSourceEnumeration',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('CreativeWork',), external_domains=(), comment='Indicates an IPTCDigitalSourceEnumeration code indicating the nature of the digital source(s) for some [[CreativeWork]].', label='digitalSourceType', contributors=(), sources=('https://github.com/schemaorg/schemaorg/issues/3392',)),
        PropertyMetadata(name='disambiguating_description', schema_name='disambiguatingDescription', schema_url='https://schema.org/disambiguatingDescription', ranges=('Text',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=('description',), domains=('Thing',), external_domains=(), comment='A sub property of description. A short description of the item used to disambiguate from other, similar items. Information from other properties (in particular, name) may be necessary for the description to be useful for disambiguation.', label='disambiguatingDescription', contributors=(), sources=()),
        PropertyMetadata(name='discussion_url', schema_name='discussionUrl', schema_url='https://schema.org/discussionUrl', ranges=('URL',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('CreativeWork',), external_domains=(), comment='A link to the page containing the comments of the CreativeWork.', label='discussionUrl', contributors=(), sources=()),
        PropertyMetadata(name='display_location', schema_name='displayLocation', schema_url='https://schema.org/displayLocation', ranges=('Place',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('CreativeWork', 'Product'), external_domains=(), comment='The location at which an item can be viewed or experienced in-person.', label='displayLocation', contributors=(), sources=('https://github.com/schemaorg/schemaorg/issues/4513',)),
        PropertyMetadata(name='edit_eidr', schema_name='editEIDR', schema_url='https://schema.org/editEIDR', ranges=('Text', 'URL'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=('identifier',), domains=('CreativeWork',), external_domains=(), comment='An [EIDR](https://eidr.org/) (Entertainment Identifier Registry) [[identifier]] representing a specific edit / edition for a work of film or television.\n\nFor example, the motion picture known as "Ghostbusters" whose [[titleEIDR]] is "10.5240/7EC7-228A-510A-053E-CBB8-J" has several edits, e.g. "10.5240/1F2A-E1C5-680A-14C6-E76B-I" and "10.5240/8A35-3BEE-6497-5D12-9E4F-3".\n\nSince schema.org types like [[Movie]] and [[TVEpisode]] can be used for both works and their multiple expressions, it is possible to use [[titleEIDR]] alone (for a general description), or alongside [[editEIDR]] for a more edit-specific description.\n', label='editEIDR', contributors=(), sources=('https://github.com/schemaorg/schemaorg/issues/2469',)),
        PropertyMetadata(name='editor', schema_name='editor', schema_url='https://schema.org/editor', ranges=('Person',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('CreativeWork',), external_domains=(), comment='Specifies the Person who edited the CreativeWork.', label='editor', contributors=(), sources=()),
        PropertyMetadata(name='educational_alignment', schema_name='educationalAlignment', schema_url='https://schema.org/educationalAlignment', ranges=('AlignmentObject',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('CreativeWork', 'LearningResource'), external_domains=(), comment='An alignment to an established educational framework.\n\nThis property should not be used where the nature of the alignment can be described using a simple property, for example to express that a resource [[teaches]] or [[assesses]] a competency.', label='educationalAlignment', contributors=(), sources=()),
        PropertyMetadata(name='educational_level', schema_name='educationalLevel', schema_url='https://schema.org/educationalLevel', ranges=('DefinedTerm', 'Text', 'URL'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('CreativeWork', 'EducationEvent', 'EducationalOccupationalCredential', 'LearningResource'), external_domains=(), comment="The level in terms of progression through an educational or training context. Examples of educational levels include 'beginner', 'intermediate' or 'advanced', and formal sets of level indicators.", label='educationalLevel', contributors=(), sources=('https://github.com/schemaorg/schemaorg/issues/1779',)),
        PropertyMetadata(name='educational_use', schema_name='educationalUse', schema_url='https://schema.org/educationalUse', ranges=('DefinedTerm', 'Text'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('CreativeWork', 'LearningResource'), external_domains=(), comment="The purpose of a work in the context of education; for example, 'assignment', 'group work'.", label='educationalUse', contributors=(), sources=()),
        PropertyMetadata(name='encoding', schema_name='encoding', schema_url='https://schema.org/encoding', ranges=('MediaObject',), external_ranges=(), inverse_of='encodesCreativeWork', superseded_by=None, supersedes=('encodings',), equivalent_properties=(), subproperty_of=(), domains=('CreativeWork',), external_domains=(), comment='A media object that encodes this CreativeWork. This property is a synonym for associatedMedia.', label='encoding', contributors=(), sources=()),
        PropertyMetadata(name='encoding_format', schema_name='encodingFormat', schema_url='https://schema.org/encodingFormat', ranges=('Text', 'URL'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=('fileFormat',), equivalent_properties=(), subproperty_of=(), domains=('CreativeWork', 'MediaObject'), external_domains=(), comment='Media type typically expressed using a MIME format (see [IANA site](http://www.iana.org/assignments/media-types/media-types.xhtml) and [MDN reference](https://developer.mozilla.org/en-US/docs/Web/HTTP/Basics_of_HTTP/MIME_types)), e.g. application/zip for a SoftwareApplication binary, audio/mpeg for .mp3 etc.\n\nIn cases where a [[CreativeWork]] has several media type representations, [[encoding]] can be used to indicate each [[MediaObject]] alongside particular [[encodingFormat]] information.\n\nUnregistered or niche encoding and file formats can be indicated instead via the most appropriate URL, e.g. defining Web page or a Wikipedia/Wikidata entry.', label='encodingFormat', contributors=(), sources=()),
        PropertyMetadata(name='encodings', schema_name='encodings', schema_url='https://schema.org/encodings', ranges=('MediaObject',), external_ranges=(), inverse_of=None, superseded_by='encoding', supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('CreativeWork',), external_domains=(), comment='A media object that encodes this CreativeWork.', label='encodings', contributors=(), sources=()),
        PropertyMetadata(name='example_of_work', schema_name='exampleOfWork', schema_url='https://schema.org/exampleOfWork', ranges=('CreativeWork',), external_ranges=(), inverse_of='workExample', superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('CreativeWork',), external_domains=(), comment='A creative work that this work is an example/instance/realization/derivation of.', label='exampleOfWork', contributors=('https://schema.org/docs/collab/bibex',), sources=()),
        PropertyMetadata(name='expires', schema_name='expires', schema_url='https://schema.org/expires', ranges=('Date', 'DateTime'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('Certification', 'CreativeWork'), external_domains=(), comment='Date the content expires and is no longer useful or available. For example a [[VideoObject]] or [[NewsArticle]] whose availability or relevance is time-limited, a [[ClaimReview]] fact check whose publisher wants to indicate that it may no longer be relevant (or helpful to highlight) after some date, or a [[Certification]] the validity has expired.', label='expires', contributors=(), sources=()),
        PropertyMetadata(name='file_format', schema_name='fileFormat', schema_url='https://schema.org/fileFormat', ranges=('Text', 'URL'), external_ranges=(), inverse_of=None, superseded_by='encodingFormat', supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('CreativeWork',), external_domains=(), comment="Media type, typically MIME format (see [IANA site](http://www.iana.org/assignments/media-types/media-types.xhtml)) of the content, e.g. application/zip of a SoftwareApplication binary. In cases where a CreativeWork has several media type representations, 'encoding' can be used to indicate each MediaObject alongside particular fileFormat information. Unregistered or niche file formats can be indicated instead via the most appropriate URL, e.g. defining Web page or a Wikipedia entry.", label='fileFormat', contributors=(), sources=()),
        PropertyMetadata(name='funder', schema_name='funder', schema_url='https://schema.org/funder', ranges=('Organization', 'Person'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=('sponsor',), domains=('CreativeWork', 'Event', 'Grant', 'MonetaryGrant', 'Organization', 'Person'), external_domains=(), comment='A person or organization that supports (sponsors) something through some kind of financial contribution.', label='funder', contributors=(), sources=()),
        PropertyMetadata(name='funding', schema_name='funding', schema_url='https://schema.org/funding', ranges=('Grant',), external_ranges=(), inverse_of='fundedItem', superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('BioChemEntity', 'CreativeWork', 'Event', 'MedicalEntity', 'Organization', 'Person', 'Product'), external_domains=(), comment='A [[Grant]] that directly or indirectly provide funding or sponsorship for this item. See also [[ownershipFundingInfo]].', label='funding', contributors=('https://schema.org/docs/collab/TP',), sources=('https://github.com/schemaorg/schemaorg/issues/383',)),
        PropertyMetadata(name='genre', schema_name='genre', schema_url='https://schema.org/genre', ranges=('DefinedTerm', 'Text', 'URL'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('BroadcastChannel', 'CreativeWork', 'MusicGroup'), external_domains=(), comment='Genre of the creative work, broadcast channel or group.', label='genre', contributors=(), sources=()),
        PropertyMetadata(name='gtin', schema_name='gtin', schema_url='https://schema.org/gtin', ranges=('Text', 'URL'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=('http://unece.org/vocab#gTINId', 'https://ref.gs1.org/voc/gtin'), subproperty_of=('identifier',), domains=('Demand', 'Offer', 'Product'), external_domains=(), comment='A Global Trade Item Number ([GTIN](https://www.gs1.org/standards/id-keys/gtin)). GTINs identify trade items, including products and services, using numeric identification codes.\n\nA correct [[gtin]] value should be a valid GTIN, which means that it should be an all-numeric string of either 8, 12, 13 or 14 digits, or a "GS1 Digital Link" URL based on such a string. The numeric component should also have a [valid GS1 check digit](https://www.gs1.org/services/check-digit-calculator) and meet the other rules for valid GTINs. See also [GS1\'s GTIN Summary](http://www.gs1.org/barcodes/technical/idkeys/gtin) and [Wikipedia](https://en.wikipedia.org/wiki/Global_Trade_Item_Number) for more details. Left-padding of the gtin values is not required or encouraged. The [[gtin]] property generalizes the earlier [[gtin8]], [[gtin12]], [[gtin13]], and [[gtin14]] properties.\n\nThe GS1 [digital link specifications](https://www.gs1.org/standards/Digital-Link/) expresses GTINs as URLs (URIs, IRIs, etc.).\nDigital Links should be populated into the [[hasGS1DigitalLink]] attribute.\n\nNote also that this is a definition for how to include GTINs in Schema.org data, and not a definition of GTINs in general - see the GS1 documentation for authoritative details.', label='gtin', contributors=(), sources=('https://github.com/schemaorg/schemaorg/issues/2288',)),
        PropertyMetadata(name='gtin12', schema_name='gtin12', schema_url='https://schema.org/gtin12', ranges=('Text',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=('gtin', 'identifier'), domains=('Demand', 'Offer', 'Product'), external_domains=(), comment='The GTIN-12 code of the product, or the product to which the offer refers. The GTIN-12 is the 12-digit GS1 Identification Key composed of a U.P.C. Company Prefix, Item Reference, and Check Digit used to identify trade items. See [GS1 GTIN Summary](http://www.gs1.org/barcodes/technical/idkeys/gtin) for more details.', label='gtin12', contributors=(), sources=()),
        PropertyMetadata(name='gtin13', schema_name='gtin13', schema_url='https://schema.org/gtin13', ranges=('Text',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=('gtin', 'identifier'), domains=('Demand', 'Offer', 'Product'), external_domains=(), comment='The GTIN-13 code of the product, or the product to which the offer refers. This is equivalent to 13-digit ISBN codes and EAN UCC-13. Former 12-digit UPC codes can be converted into a GTIN-13 code by simply adding a preceding zero. See [GS1 GTIN Summary](http://www.gs1.org/barcodes/technical/idkeys/gtin) for more details.', label='gtin13', contributors=('https://schema.org/docs/collab/GoodRelationsTerms',), sources=()),
        PropertyMetadata(name='gtin14', schema_name='gtin14', schema_url='https://schema.org/gtin14', ranges=('Text',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=('gtin', 'identifier'), domains=('Demand', 'Offer', 'Product'), external_domains=(), comment='The GTIN-14 code of the product, or the product to which the offer refers. See [GS1 GTIN Summary](http://www.gs1.org/barcodes/technical/idkeys/gtin) for more details.', label='gtin14', contributors=('https://schema.org/docs/collab/GoodRelationsTerms',), sources=()),
        PropertyMetadata(name='gtin8', schema_name='gtin8', schema_url='https://schema.org/gtin8', ranges=('Text',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=('gtin', 'identifier'), domains=('Demand', 'Offer', 'Product'), external_domains=(), comment='The GTIN-8 code of the product, or the product to which the offer refers. This code is also known as EAN/UCC-8 or 8-digit EAN. See [GS1 GTIN Summary](http://www.gs1.org/barcodes/technical/idkeys/gtin) for more details.', label='gtin8', contributors=('https://schema.org/docs/collab/GoodRelationsTerms',), sources=()),
        PropertyMetadata(name='has_adult_consideration', schema_name='hasAdultConsideration', schema_url='https://schema.org/hasAdultConsideration', ranges=('AdultOrientedEnumeration',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('Offer', 'Product'), external_domains=(), comment='Used to tag an item to be intended or suitable for consumption or use by adults only.', label='hasAdultConsideration', contributors=(), sources=('https://github.com/schemaorg/schemaorg/issues/2989',)),
        PropertyMetadata(name='has_certification', schema_name='hasCertification', schema_url='https://schema.org/hasCertification', ranges=('Certification',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=('http://unece.org/vocab#ApplicableCertificate',), subproperty_of=('https://spec.edmcouncil.org/fibo/ontology/FND/Arrangements/Documents/isReferencedIn', 'https://www.omg.org/spec/Commons/Classifiers/isClassifiedBy'), domains=('Organization', 'Person', 'Place', 'Product', 'Service'), external_domains=(), comment='Certification information about a product, organization, service, place, or person.', label='hasCertification', contributors=(), sources=('https://github.com/schemaorg/schemaorg/issues/3230',)),
        PropertyMetadata(name='has_energy_consumption_details', schema_name='hasEnergyConsumptionDetails', schema_url='https://schema.org/hasEnergyConsumptionDetails', ranges=('EnergyConsumptionDetails',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('Product',), external_domains=(), comment='Defines the energy efficiency Category (also known as "class" or "rating") for a product according to an international energy efficiency standard.', label='hasEnergyConsumptionDetails', contributors=(), sources=('https://github.com/schemaorg/schemaorg/issues/2670',)),
        PropertyMetadata(name='has_gs1_digital_link', schema_name='hasGS1DigitalLink', schema_url='https://schema.org/hasGS1DigitalLink', ranges=('URL',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=('identifier',), domains=('Offer', 'Organization', 'Place', 'Product'), external_domains=(), comment='The <a href="https://www.gs1.org/standards/gs1-digital-link">GS1 digital link</a> associated with the object. This URL should conform to the particular requirements of digital links. The link should only contain the Application Identifiers (AIs) that are relevant for the entity being annotated, for instance a [[Product]] or an [[Organization]], and for the correct granularity. In particular, for products:<ul><li>A Digital Link that contains a serial number (AI <code>21</code>) should only be present on instances of [[IndividualProduct]]</li><li>A Digital Link that contains a lot number (AI <code>10</code>) should be annotated as [[SomeProducts]] if only products from that lot are sold, or [[IndividualProduct]] if there is only a specific product.</li><li>A Digital Link that contains a global model number (AI <code>8013</code>) should be attached to a [[Product]] or a [[ProductModel]].</li></ul> Other item types should be adapted similarly.', label='hasGS1DigitalLink', contributors=(), sources=('https://github.com/schemaorg/schemaorg/issues/3475',)),
        PropertyMetadata(name='has_measurement', schema_name='hasMeasurement', schema_url='https://schema.org/hasMeasurement', ranges=('QuantitativeValue',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('Certification', 'Offer', 'Product', 'SizeSpecification'), external_domains=(), comment='A measurement of an item, For example, the inseam of pants, the wheel size of a bicycle, the gauge of a screw, or the carbon footprint measured for certification by an authority. Usually an exact measurement, but can also be a range of measurements for adjustable products, for example belts and ski bindings.', label='hasMeasurement', contributors=(), sources=('https://github.com/schemaorg/schemaorg/issues/2811',)),
        PropertyMetadata(name='has_merchant_return_policy', schema_name='hasMerchantReturnPolicy', schema_url='https://schema.org/hasMerchantReturnPolicy', ranges=('MerchantReturnPolicy',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=('hasProductReturnPolicy',), equivalent_properties=(), subproperty_of=(), domains=('Offer', 'Organization', 'Product'), external_domains=(), comment='Specifies a MerchantReturnPolicy that may be applicable.', label='hasMerchantReturnPolicy', contributors=(), sources=('https://github.com/schemaorg/schemaorg/issues/2288',)),
        PropertyMetadata(name='has_part', schema_name='hasPart', schema_url='https://schema.org/hasPart', ranges=('CreativeWork',), external_ranges=(), inverse_of='isPartOf', superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('CreativeWork',), external_domains=(), comment='Indicates an item or CreativeWork that is part of this item, or CreativeWork (in some sense).', label='hasPart', contributors=('https://schema.org/docs/collab/bibex',), sources=()),
        PropertyMetadata(name='has_product_return_policy', schema_name='hasProductReturnPolicy', schema_url='https://schema.org/hasProductReturnPolicy', ranges=('ProductReturnPolicy',), external_ranges=(), inverse_of=None, superseded_by='hasMerchantReturnPolicy', supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('Organization', 'Product'), external_domains=(), comment='Indicates a ProductReturnPolicy that may be applicable.', label='hasProductReturnPolicy', contributors=(), sources=('https://github.com/schemaorg/schemaorg/issues/2288',)),
        PropertyMetadata(name='headline', schema_name='headline', schema_url='https://schema.org/headline', ranges=('Text',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('CreativeWork',), external_domains=(), comment='Headline of the article.', label='headline', contributors=(), sources=()),
        PropertyMetadata(name='height', schema_name='height', schema_url='https://schema.org/height', ranges=('Distance', 'QuantitativeValue'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('MediaObject', 'OfferShippingDetails', 'Person', 'Product', 'ShippingConditions', 'VisualArtwork'), external_domains=(), comment='The height of the item.', label='height', contributors=(), sources=('https://github.com/schemaorg/schemaorg/issues/3617',)),
        PropertyMetadata(name='identifier', schema_name='identifier', schema_url='https://schema.org/identifier', ranges=('PropertyValue', 'Text', 'URL'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=('http://purl.org/dc/terms/identifier', 'https://www.omg.org/spec/Commons/Identifiers/identifiedBy'), subproperty_of=(), domains=('Thing',), external_domains=(), comment='The identifier property represents any kind of identifier for any kind of [[Thing]], such as ISBNs, GTIN codes, UUIDs etc. Schema.org provides dedicated properties for representing many of these, either as textual strings or as URL (URI) links. See [background notes](/docs/datamodel.html#identifierBg) for more details.\n        ', label='identifier', contributors=(), sources=()),
        PropertyMetadata(name='image', schema_name='image', schema_url='https://schema.org/image', ranges=('ImageObject', 'URL'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=('http://ogp.me/ns#image',), subproperty_of=(), domains=('Thing',), external_domains=(), comment='An image of the item. This can be a [[URL]] or a fully described [[ImageObject]].', label='image', contributors=(), sources=()),
        PropertyMetadata(name='in_language', schema_name='inLanguage', schema_url='https://schema.org/inLanguage', ranges=('Language', 'Text'), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=('language',), equivalent_properties=('http://purl.org/dc/terms/language',), subproperty_of=(), domains=('BroadcastService', 'CommunicateAction', 'CreativeWork', 'Event', 'LinkRole', 'PronounceableText', 'WriteAction'), external_domains=(), comment='The language of the content or performance or used in an action. Please use one of the language codes from the [IETF BCP 47 standard](http://tools.ietf.org/html/bcp47). See also [[availableLanguage]].', label='inLanguage', contributors=(), sources=('https://github.com/schemaorg/schemaorg/issues/2382',)),
        PropertyMetadata(name='in_product_group_with_id', schema_name='inProductGroupWithID', schema_url='https://schema.org/inProductGroupWithID', ranges=('Text',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=('http://unece.org/vocab#variantId',), subproperty_of=(), domains=('Product',), external_domains=(), comment='Indicates the [[productGroupID]] for a [[ProductGroup]] that this product [[isVariantOf]]. ', label='inProductGroupWithID', contributors=(), sources=('https://github.com/schemaorg/schemaorg/issues/1797',)),
        PropertyMetadata(name='includes_object', schema_name='includesObject', schema_url='https://schema.org/includesObject', ranges=('TypeAndQuantityNode',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('Demand', 'Offer', 'ProductCollection'), external_domains=(), comment='This links to a node or nodes indicating the exact quantity of the products included in  an [[Offer]] or [[ProductCollection]].', label='includesObject', contributors=('https://schema.org/docs/collab/GoodRelationsTerms',), sources=()),
        PropertyMetadata(name='interaction_statistic', schema_name='interactionStatistic', schema_url='https://schema.org/interactionStatistic', ranges=('InteractionCounter',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=('interactionCount',), equivalent_properties=(), subproperty_of=(), domains=('CreativeWork', 'Organization', 'Person'), external_domains=(), comment='The number of interactions for the CreativeWork using the WebSite or SoftwareApplication. The most specific child type of InteractionCounter should be used.', label='interactionStatistic', contributors=(), sources=('https://github.com/schemaorg/schemaorg/issues/2421',)),
        PropertyMetadata(name='interactivity_type', schema_name='interactivityType', schema_url='https://schema.org/interactivityType', ranges=('Text',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=(), domains=('CreativeWork',), external_domains=(), comment="The predominant mode of learning supported by the learning resource. Acceptable values are 'active', 'expositive', or 'mixed'.", label='interactivityType', contributors=(), sources=()),
        PropertyMetadata(name='interpreted_as_claim', schema_name='interpretedAsClaim', schema_url='https://schema.org/interpretedAsClaim', ranges=('Claim',), external_ranges=(), inverse_of=None, superseded_by=None, supersedes=(), equivalent_properties=(), subproperty_of=('description',), domains=('CreativeWork', 'MediaObject'), external_domains=(), comment='Used to indicate a specific claim contained, implied, translated or refined from the content of a [[MediaObject]] or other [[CreativeWork]]. The interpreting party can be indicated using [[claimInterpreter]].', label='interpretedAsClaim', contributors=(), sources=('https://github.com/schemaorg/schemaorg/issues/2450',)),
